import os
import re
import unicodedata
import hashlib
import hmac
import secrets
from pathlib import PurePosixPath
from flask import Flask, request, jsonify, abort

app = Flask(__name__)
app.secret_key = secrets.token_hex(32)

UPLOAD_DIR = '/var/app/uploads'
ALLOWED_EXTENSIONS = {'.txt', '.pdf', '.png', '.jpg', '.doc', '.csv'}
MAX_FILENAME_LEN = 255
API_TOKENS = {}

# Allow only safe user-id characters to prevent path injection via user_id
SAFE_USER_ID_RE = re.compile(r'^[A-Za-z0-9_-]{1,64}$')


def generate_api_token(user_id):
    token = secrets.token_urlsafe(32)
    API_TOKENS[token] = user_id
    return token


def get_safe_user_dir(user_id):
    """Validate user_id before using it in a filesystem path.
    Prevents path injection through a malicious/unexpected user_id."""
    if not isinstance(user_id, str) or not SAFE_USER_ID_RE.match(user_id):
        return None
    return os.path.join(UPLOAD_DIR, user_id)


def require_auth(f):
    from functools import wraps
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('Authorization', '').replace('Bearer ', '')
        if not token or token not in API_TOKENS:
            abort(401)
        request.user_id = API_TOKENS[token]
        return f(*args, **kwargs)
    return decorated


def check_path_traversal(filepath):
    """Check for path traversal sequences AFTER normalization.
    This catches traversal attempts including unicode-normalized variants."""
    dangerous_patterns = ['../', '..\\', '%2e%2e', '%2f', '%5c']
    lower_path = filepath.lower()
    for pattern in dangerous_patterns:
        if pattern in lower_path:
            return False
    return True


def sanitize_filename(filename):
    """Multi-layer filename sanitization pipeline.

    Security layers:
    1. Length check
    2. Unicode normalization (NFC) for consistent processing
    3. Path traversal detection (AFTER normalization)
    4. Extension whitelist
    5. Null byte removal
    6. Final path resolution check
    """
    if not filename or len(filename) > MAX_FILENAME_LEN:
        return None

    # Remove null bytes
    filename = filename.replace('\x00', '')

    # Normalize unicode to NFC form BEFORE traversal check
    # This prevents unicode normalization from introducing traversal sequences
    filename = unicodedata.normalize('NFC', filename)

    # Check for traversal patterns after normalization
    if not check_path_traversal(filename):
        return None

    # Verify extension
    _, ext = os.path.splitext(filename)
    if ext.lower() not in ALLOWED_EXTENSIONS:
        return None

    # Strip any remaining directory components
    filename = PurePosixPath(filename).name

    # Final safety check: ensure no traversal in the resolved name
    if '..' in filename:
        return None

    # Verify the final path stays within bounds
    return filename


def compute_file_hash(content):
    return hashlib.sha256(content).hexdigest()


@app.route('/api/upload', methods=['POST'])
@require_auth
def upload_file():
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    if not file.filename:
        return jsonify({'error': 'Empty filename'}), 400

    safe_name = sanitize_filename(file.filename)
    if safe_name is None:
        return jsonify({'error': 'Invalid filename'}), 400

    content = file.read()
    if len(content) > 10 * 1024 * 1024:  # 10MB limit
        return jsonify({'error': 'File too large'}), 413

    file_hash = compute_file_hash(content)

    # Construct final path using user's directory (user_id validated first)
    user_dir = get_safe_user_dir(request.user_id)
    if user_dir is None:
        return jsonify({'error': 'Invalid user'}), 400
    os.makedirs(user_dir, exist_ok=True)

    final_path = os.path.join(user_dir, safe_name)

    # Final resolution check - ensure path is within user_dir
    real_final = os.path.realpath(final_path)
    real_user_dir = os.path.realpath(user_dir)
    if not real_final.startswith(real_user_dir + os.sep) and real_final != real_user_dir:
        return jsonify({'error': 'Invalid path'}), 400

    # Write file
    with open(final_path, 'wb') as f:
        f.write(content)

    return jsonify({
        'status': 'uploaded',
        'filename': safe_name,
        'hash': file_hash,
        'size': len(content)
    }), 201


@app.route('/api/files/<filename>', methods=['GET'])
@require_auth
def download_file(filename):
    safe_name = sanitize_filename(filename)
    if safe_name is None:
        abort(400)

    user_dir = get_safe_user_dir(request.user_id)
    if user_dir is None:
        abort(400)
    final_path = os.path.join(user_dir, safe_name)

    # Resolution check
    real_final = os.path.realpath(final_path)
    real_user_dir = os.path.realpath(user_dir)
    if not real_final.startswith(real_user_dir + os.sep) and real_final != real_user_dir:
        abort(400)

    if not os.path.isfile(final_path):
        abort(404)

    with open(final_path, 'rb') as f:
        content = f.read()

    return content, 200, {'Content-Type': 'application/octet-stream'}


@app.route('/api/files', methods=['GET'])
@require_auth
def list_files():
    user_dir = get_safe_user_dir(request.user_id)
    if user_dir is None:
        abort(400)
    if not os.path.isdir(user_dir):
        return jsonify({'files': []})

    files = []
    for fname in os.listdir(user_dir):
        fpath = os.path.join(user_dir, fname)
        if os.path.isfile(fpath):
            stat = os.stat(fpath)
            files.append({
                'name': fname,
                'size': stat.st_size,
                'modified': stat.st_mtime
            })

    return jsonify({'files': files})


if __name__ == '__main__':
    app.run(host='127.0.0.1', port=8080, debug=False)
